query:
SELECT 'Senate' as chamber, state_name, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party, primary_date
FROM senate_races WHERE status = 'Primary' ORDER BY state_name;

SELECT 'House' as chamber, state_name, district, status, candidate1_name, candidate1_party, candidate2_name, candidate2_party, primary_date
FROM house_races WHERE status = 'Primary' ORDER BY state_name, district;

